{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    for field in ("nodes", "required_symbols", "_case_nonce"):
        if field not in case:
            raise ValueError("missing required field: " + field)

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    nonce = case["_case_nonce"]

    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be a list")
    if not isinstance(nonce, str):
        raise ValueError("_case_nonce must be a string")

    required = set()
    for symbol in required_symbols:
        if not isinstance(symbol, str) or not symbol:
            raise ValueError("required symbols must be non-empty strings")
        if symbol in required:
            raise ValueError("required_symbols must not contain duplicates")
        required.add(symbol)

    by_id = {}
    roots = []
    required_node_fields = ("id", "parent", "symbol", "depth", "removable", "utility")

    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in required_node_fields:
            if field not in node:
                raise ValueError("node missing required field: " + field)

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or not node_id:
            raise ValueError("node id must be a non-empty string")
        if node_id in by_id:
            raise ValueError("node ids must be unique")
        if parent is not None and (not isinstance(parent, str) or not parent):
            raise ValueError("parent must be null or a non-empty string")
        if not isinstance(symbol, str) or not symbol:
            raise ValueError("symbol must be a non-empty string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be a boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise ValueError("utility must be numeric")
        if not math.isfinite(utility):
            raise ValueError("utility must be finite")

        by_id[node_id] = node
        if parent is None:
            roots.append(node_id)

    if len(roots) != 1:
        raise ValueError("the tree must have exactly one root")
    root_id = roots[0]
    root = by_id[root_id]
    if root["depth"] != 0:
        raise ValueError("root depth must be zero")

    children = {node_id: set() for node_id in by_id}
    symbol_counts = {}
    for node in nodes:
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1
        if parent is not None:
            if parent not in by_id:
                raise ValueError("parent does not reference an existing node")
            if by_id[parent]["depth"] + 1 != node["depth"]:
                raise ValueError("node depth is inconsistent with its parent")
            children[parent].add(node_id)

    for symbol in required:
        if symbol_counts.get(symbol, 0) == 0:
            raise ValueError("required symbol is not represented: " + symbol)

    retained = set(by_id)
    removal_order = []
    candidate_ids = sorted(by_id, key=lambda node_id: (-by_id[node_id]["depth"], node_id))

    for node_id in candidate_ids:
        node = by_id[node_id]
        symbol = node["symbol"]
        if node_id == root_id or not node["removable"] or symbol in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue

        symbol_counts[symbol] -= 1
        if any(symbol_counts.get(required_symbol, 0) == 0 for required_symbol in required):
            symbol_counts[symbol] += 1
            continue

        retained.remove(node_id)
        removal_order.append(node_id)

    return {
        "retained_ids": sorted(retained),
        "removal_order": removal_order
    }
